import sales from './sales.json' with {type:'json'};

const ALLOWED_ARGS = new Set(['start_date', 'end_date']);

// Parse and validate an ISO calendar date string (YYYY-MM-DD).
// Returns a Date at UTC midnight, or null if malformed.
function parseDate(value) {
  if (typeof value !== 'string') return null;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!m) return null;
  const year = Number(m[1]);
  const month = Number(m[2]);
  const day = Number(m[3]);
  if (month < 1 || month > 12) return null;
  if (day < 1 || day > 31) return null;
  const d = new Date(Date.UTC(year, month - 1, day));
  if (
    d.getUTCFullYear() !== year ||
    d.getUTCMonth() !== month - 1 ||
    d.getUTCDate() !== day
  ) {
    return null;
  }
  return d;
}

export async function listTools() {
  return [
    {
      name: 'sales_report',
      description:
        'Sum sales rows inclusively within an ISO date range and report the total amount and row count.',
      inputSchema: {
        type: 'object',
        properties: {
          start_date: {
            type: 'string',
            description: 'Inclusive start date as an ISO string (YYYY-MM-DD).',
          },
          end_date: {
            type: 'string',
            description: 'Inclusive end date as an ISO string (YYYY-MM-DD).',
          },
        },
        required: ['start_date', 'end_date'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'sales_report') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Reject extra / unknown fields.
  for (const key of Object.keys(args)) {
    if (!ALLOWED_ARGS.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }

  const { start_date, end_date } = args;
  if (start_date === undefined) {
    throw new Error('start_date is required');
  }
  if (end_date === undefined) {
    throw new Error('end_date is required');
  }

  const start = parseDate(start_date);
  if (!start) {
    throw new Error(`Invalid start_date: ${start_date}`);
  }
  const end = parseDate(end_date);
  if (!end) {
    throw new Error(`Invalid end_date: ${end_date}`);
  }
  if (start.getTime() > end.getTime()) {
    throw new Error('start_date must not be after end_date');
  }

  const startTime = start.getTime();
  const endTime = end.getTime();
  let total = 0;
  let count = 0;
  for (const row of sales) {
    const rd = parseDate(row.date);
    if (!rd) continue;
    const t = rd.getTime();
    if (t >= startTime && t <= endTime) {
      total += row.amount;
      count += 1;
    }
  }

  return {
    content: [
      {
        type: 'text',
        text: `Total: ${total}\nRows: ${count}`,
      },
    ],
  };
}

